/**
 * G188: every making tool with a CC0 tool_animation plays it in the Make panel while its recipe runs.
 *
 * The table (public/js/make-tool-sheets.js) is generated by tools/build-make-tool-sheets.py from the
 * OGA dump's `<class>__x1_tool_animation` grids, repacked into one row. These tests check the table
 * against the shipped sheets (sizes, frame counts), against the item SWFs' own tool_animation scenes
 * when tinyspeck/glitch-items is present, and run the builder's --check.
 */
import { before, describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { inflateSync } from 'node:zlib';
import { MAKE_TOOL_SHEETS } from '../public/js/make-tool-sheets.js';
import { TOOL_STAND_INS, listMakingTools, loadRecipeCatalogFromFile } from '../public/js/making.js';

const spike = join(dirname(fileURLToPath(import.meta.url)), '..');
const pub = join(spike, 'public');
const makingDir = join(pub, 'assets/sprites/making');
const auditCandidates = [process.env.GLITCH_AUDIT, dirname(spike), join(homedir(), 'Documents/glitch-audit')];
const audit = auditCandidates.find((d) => d && existsSync(join(d, 'glitch-items')));

// The four machines (machine_stand assemblies) have no tool_animation scene in glitch-items or the
// OGA dump; they draw their own `active` states instead, so the Make panel keeps their icon.
const NO_SHEET = ['blockmaker', 'fuelmaker', 'metalmaker', 'woodworker'];

/** Width and height of a lossless (VP8L) or extended (VP8X) WebP. */
function webpSize(file) {
  const b = readFileSync(file);
  assert.equal(b.toString('ascii', 0, 4), 'RIFF', `${file}: not RIFF`);
  assert.equal(b.toString('ascii', 8, 12), 'WEBP', `${file}: not WebP`);
  const kind = b.toString('ascii', 12, 16);
  if (kind === 'VP8L') {
    const bits = b.readUInt32LE(21);
    return [(bits & 0x3fff) + 1, ((bits >> 14) & 0x3fff) + 1];
  }
  assert.equal(kind, 'VP8X', `${file}: ${kind}`);
  return [b.readUIntLE(24, 3) + 1, b.readUIntLE(27, 3) + 1];
}

/** {scene: frame count} from a CWS/FWS SWF's DefineSceneAndFrameLabelData (tag 86). Data only. */
function swfScenes(file) {
  const raw = readFileSync(file);
  const sig = raw.toString('ascii', 0, 3);
  const body = sig === 'CWS' ? inflateSync(raw.subarray(8)) : sig === 'FWS' ? raw.subarray(8) : null;
  assert.ok(body, `${file}: unsupported SWF ${sig}`);
  let i = Math.ceil((5 + 4 * (body[0] >> 3)) / 8);
  const total = body.readUInt16LE(i + 2);
  i += 4;
  const u30 = (data, at) => {
    let r = 0; let s = 0; let c;
    do { c = data[at++]; r += (c & 0x7f) * 2 ** s; s += 7; } while (c & 0x80);
    return [r, at];
  };
  while (i < body.length) {
    const head = body.readUInt16LE(i); i += 2;
    const code = head >> 6;
    let len = head & 0x3f;
    if (len === 0x3f) { len = body.readUInt32LE(i); i += 4; }
    const data = body.subarray(i, i + len); i += len;
    if (code === 86) {
      let [n, j] = u30(data, 0);
      const scenes = [];
      while (n--) {
        let off;
        [off, j] = u30(data, j);
        const end = data.indexOf(0, j);
        scenes.push([data.toString('latin1', j, end), off]);
        j = end + 1;
      }
      return Object.fromEntries(scenes.map(([name, off], k) => [name, (scenes[k + 1]?.[1] ?? total) - off]));
    }
    if (code === 0) break;
  }
  return {};
}

describe('G188 Make panel tool animations', () => {
  before(async () => {
    await loadRecipeCatalogFromFile(join(pub, 'assets/content/recipes.json'));
  });

  it('every making tool and stand-in has a sheet, except the four machines', () => {
    const tools = new Set(listMakingTools().map((t) => t.classTsid));
    for (const ids of Object.values(TOOL_STAND_INS)) for (const id of ids) tools.add(id);
    assert.ok(tools.size >= 31, `only ${tools.size} making tools`);
    const without = [...tools].filter((id) => !MAKE_TOOL_SHEETS[id]).sort();
    assert.deepEqual(without, NO_SHEET);
    for (const id of Object.keys(MAKE_TOOL_SHEETS)) assert.ok(tools.has(id), `${id} is not a making tool`);
  });

  it('each sheet is one row of its frames at the table\'s size', () => {
    for (const [id, s] of Object.entries(MAKE_TOOL_SHEETS)) {
      const file = join(pub, s.url);
      assert.ok(existsSync(file), `${id}: ${s.url} missing`);
      const d = s.density || 1;
      assert.deepEqual(webpSize(file), [s.frames * s.fw * d, s.fh * d], `${id}: ${s.url}`);
      assert.ok(Number.isInteger(s.frames) && s.frames > 1, `${id} frames`);
      if (s.durationMs) assert.equal(id, 'fruit_changing_machine', `${id}: only the 3x Fruit Changing Machine keeps its own timing`);
      else assert.equal(s.fps, 30, `${id}: TSEngineConstants.TARGET_FRAMERATE`);
      // Fits the .mp-tool-wrap box (112 x 104) and never upscales the 1x art past 1.6.
      assert.ok(s.scale > 0 && s.scale <= 1.6, `${id} scale ${s.scale}`);
      assert.ok(s.fw * s.scale <= 112 && s.fh * s.scale <= 104, `${id}: ${s.fw}x${s.fh} at ${s.scale}`);
    }
    // The Grand Ol' Grinder is unchanged from 9d736239: 83 frames of 50 x 79 at 1.18.
    assert.deepEqual({ ...MAKE_TOOL_SHEETS.grand_ol_grinder }, {
      url: 'assets/sprites/making/grand_ol_grinder-work.webp', fw: 50, fh: 79, frames: 83, fps: 30, scale: 1.18,
    });
    // The plain Grinder's own sheet (850 x 435, 17 x 5 cells of 50 x 87, 83 frames).
    assert.deepEqual([MAKE_TOOL_SHEETS.ore_grinder.fw, MAKE_TOOL_SHEETS.ore_grinder.fh, MAKE_TOOL_SHEETS.ore_grinder.frames], [50, 87, 83]);
  });

  it('ships no orphan sheets: every -work file is in the table, and the old grids are gone', () => {
    const urls = new Set(Object.values(MAKE_TOOL_SHEETS).map((s) => s.url.replace('assets/sprites/making/', '')));
    for (const f of readdirSync(makingDir)) {
      if (/-work(@3x)?\.(webp|png)$/.test(f)) assert.ok(urls.has(f), `${f} is not in the table`);
      // irrigator_9000-tool.png is the watering pour (game.js IRRIGATOR_TOOL_SHEET), not a Make panel sheet.
      if (f.endsWith('-tool.png')) assert.equal(f, 'irrigator_9000-tool.png', `${f}: unused grid`);
    }
  });

  it('frame counts match each item SWF\'s tool_animation scene', { skip: !audit && 'glitch-items missing' }, () => {
    const swfs = readFileSync(join(spike, 'tools/build-make-tool-sheets.py'), 'utf8')
      .matchAll(/^ {4}'([a-z_]+)': \('[^']+', \d+, \d+, \d+, (\d+), '([^']+\.swf)'/gm);
    let n = 0;
    for (const [, id, frames, swf] of swfs) {
      assert.equal(Number(frames), MAKE_TOOL_SHEETS[id].frames, `${id}: plan vs table`);
      assert.equal(swfScenes(join(audit, 'glitch-items', swf)).tool_animation, MAKE_TOOL_SHEETS[id].frames, `${id}: ${swf}`);
      n++;
    }
    assert.equal(n, Object.keys(MAKE_TOOL_SHEETS).length - 1, 'every built sheet has a SWF in the plan');
  });

  it('the Make panel plays the table, and only the table', () => {
    const game = readFileSync(join(pub, 'game.js'), 'utf8');
    const css = readFileSync(join(pub, 'style.css'), 'utf8');
    assert.match(game, /import \{ MAKE_TOOL_SHEETS \} from '\.\/js\/make-tool-sheets\.js\?v=g188-\d+'/);
    assert.match(game, /const toolVisual = makeToolSheetVisual\(toolInUse\) \|\| makeToolSheetVisual\(recipe\.tool\)\n\s+\|\| `<img class="mp-tool"/);
    assert.match(game, /--mp-steps:\$\{sheet\.frames\}/);
    assert.match(game, /sheet\.durationMs \|\| Math\.round\(\(sheet\.frames \/ sheet\.fps\) \* 1000\)/);
    assert.match(css, /\.make-progress \.mp-tool-sheet \{[\s\S]*?animation: make-tool-sheet var\(--mp-dur\) steps\(var\(--mp-steps\), end\) infinite;/);
    assert.match(css, /@keyframes make-tool-sheet \{[\s\S]*?calc\(-1 \* var\(--mp-row\)\) 0/);
    assert.doesNotMatch(css, /mp-tool-grand-ol-grinder|mp-tool-fruit-machine/);
    // A per-tool icon wobble (.mp-tool[data-tool=...], more specific) would replace the sheet's animation.
    assert.doesNotMatch(css, /\.mp-tool\[data-tool=/);
    // prefers-reduced-motion still stops it (the sheet is also an .mp-tool).
    assert.match(css, /@media \(prefers-reduced-motion: reduce\) \{\s*\.make-progress \.mp-tool,/);
    assert.ok(css.indexOf('.make-progress .mp-tool-sheet {') < css.indexOf('@media (prefers-reduced-motion: reduce) {\n  .make-progress .mp-tool,'));
  });

  it('the sheets and the table are current (tools/build-make-tool-sheets.py --check)', { skip: !existsSync('/opt/homebrew/bin/python3.11') && 'python3.11 missing' }, () => {
    const out = execFileSync('python3.11', ['-I', join(spike, 'tools/build-make-tool-sheets.py'), '--check'], { encoding: 'utf8' });
    assert.match(out, /^ok/m);
  });
});
